import{FakeObservables}from"chrome://resources/ash/common/fake_observables.js";import{PromiseResolver}from"chrome://resources/ash/common/promise_resolver.js";import{assert}from"chrome://resources/js/assert.js";import{fakeFirmwareUpdates,fakeInstallationProgress,fakeInstallationProgressFailure}from"./fake_data.js";import{UpdateState}from"./firmware_update.mojom-webui.js";import{getUpdateProvider,setUseFakeProviders}from"./mojo_interface_provider.js";export const ON_PROGRESS_CHANGED="UpdateProgressObserver_onStatusChanged";export class FakeUpdateController{constructor(){this.observables=new FakeObservables;this.completedFirmwareUpdates=new Set;this.startUpdatePromise=null;this.deviceId="";this.isUpdateInProgress=false;this.updateIntervalInMs=1e3;this.updateCompletedPromise=null;setUseFakeProviders(true);this.registerObservables()}addObserver(remote){this.isUpdateInProgress=true;this.updateCompletedPromise=new PromiseResolver;this.startUpdatePromise=this.observeWithArg(ON_PROGRESS_CHANGED,this.deviceId,(update=>{remote.onStatusChanged(update);if(update.state===UpdateState.kSuccess||update.state===UpdateState.kFailed){this.isUpdateInProgress=false;this.completedFirmwareUpdates.add(this.deviceId);this.updateDeviceList();this.observables.stopTriggerOnIntervalWithArg(ON_PROGRESS_CHANGED,this.deviceId);assert(this.updateCompletedPromise);this.updateCompletedPromise.resolve()}}))}beginUpdate(deviceId,path){assert(deviceId);assert(path);assert(this.startUpdatePromise);this.triggerProgressChangedObserver()}setDeviceIdForUpdateInProgress(deviceId){this.deviceId=deviceId}setFakeInstallationProgress(deviceId,installationProgress){this.observables.setObservableDataForArg(ON_PROGRESS_CHANGED,deviceId,installationProgress)}getStartUpdatePromiseForTesting(){return this.startUpdatePromise}triggerProgressChangedObserver(){this.observables.startTriggerOnIntervalWithArg(ON_PROGRESS_CHANGED,this.deviceId,this.updateIntervalInMs)}registerObservables(){this.observables.registerObservableWithArg(ON_PROGRESS_CHANGED);fakeFirmwareUpdates.flat().forEach((({deviceId:deviceId})=>{if(deviceId==="3"){this.setFakeInstallationProgress(deviceId,fakeInstallationProgressFailure)}else{this.setFakeInstallationProgress(deviceId,fakeInstallationProgress)}}))}reset(){this.stopTriggerIntervals();this.observables=new FakeObservables;this.completedFirmwareUpdates.clear();this.deviceId="";this.isUpdateInProgress=false;this.registerObservables()}stopTriggerIntervals(){this.observables.stopAllTriggerIntervals()}observeWithArg(methodName,arg,callback){return new Promise((resolve=>{this.observables.observeWithArg(methodName,arg,callback);resolve()}))}getIsUpdateInProgressForTesting(){return this.isUpdateInProgress}setUpdateIntervalInMs(intervalMs){this.updateIntervalInMs=intervalMs}updateDeviceList(){const updatedFakeFirmwareUpdates=fakeFirmwareUpdates.flat().filter((u=>!this.completedFirmwareUpdates.has(u.deviceId)));const provider=getUpdateProvider();provider.setFakeFirmwareUpdates([updatedFakeFirmwareUpdates]);provider.triggerDeviceAddedObserver()}getUpdateCompletedPromiseForTesting(){assert(this.updateCompletedPromise!=null);return this.updateCompletedPromise.promise}getCompletedFirmwareUpdatesForTesting(){return this.completedFirmwareUpdates}}